static constexpr size_t N = 64;
std::atomic<size_t> head{0}, tail{0};
Event buf[N];

bool post(const Event& e) {              /* single producer */
  auto t = tail.load(std::memory_order_relaxed);
  if ((t + 1) % N == head.load(std::memory_order_acquire)) return false;  /* full */
  buf[t] = e;
  tail.store((t + 1) % N, std::memory_order_release);
  tail.notify_one();
  return true;
}
